using System.Security.Cryptography;

namespace HPD.Base;

/// <summary>Loads the exact built-in L80 reports reproduced by executable provider certification.</summary>
internal static class BaseLogicalIndexBuiltInCertification
{
    internal static BaseLogicalIndexCertificationReport LoadFrozenExecutedReport(string storeProviderKind)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(storeProviderKind);
        string encoded = storeProviderKind switch
        {
            "inmemory" => InMemoryReport,
            "sqlite" => SqliteReport,
            _ => throw new ArgumentOutOfRangeException(nameof(storeProviderKind)),
        };
        string expectedId = storeProviderKind == "inmemory"
            ? "hpd.base.inMemory.logicalIndexes"
            : "hpd.base.sqlite.logicalIndexes";
        BaseLogicalIndexCertificationReport report = BaseLogicalIndexFrozenReportCodec.Decode(
            Convert.FromBase64String(encoded));
        if (!string.Equals(report.ProviderId, expectedId, StringComparison.Ordinal)
            || report.ProviderVersion != 1
            || !string.Equals(report.StoreProviderKind, storeProviderKind, StringComparison.Ordinal)
            || !CryptographicOperations.FixedTimeEquals(
                report.ProductionCapabilityChecksum.AsSpan(),
                BaseLogicalIndexProviderContract.BuiltInCapability().Checksum.AsSpan())
            || !CryptographicOperations.FixedTimeEquals(
                report.BoundedCertificationCapabilityChecksum.AsSpan(),
                BaseLogicalIndexProviderContract.BoundedCertificationCapability().Checksum.AsSpan()))
            throw new InvalidOperationException("base.logicalIndex.certificationReportInvalid");
        return report;
    }

